class DictCache:
    def __init__(self):
        self.data = {}
    def get(self, key):
        return self.data.get(key)
    def put(self, key, value):
        self.data[key] = value

cache = DictCache()
assert allow_request(cache, 'red', capacity=3, refill_rate=2.0, current_time=10.0)
assert allow_request(cache, 'red', tokens_requested=2, capacity=3, refill_rate=2.0, current_time=10.0)
assert not allow_request(cache, 'red', capacity=3, refill_rate=2.0, current_time=10.0)
assert cache.get('rate_limit:red').tokens == 0
assert allow_request(cache, 'blue', capacity=3, refill_rate=2.0, current_time=10.0)
assert not allow_request(cache, 'red', tokens_requested=3, capacity=3, refill_rate=2.0, current_time=11.0)
assert cache.get('rate_limit:red').tokens == 2.0
assert allow_request(cache, 'red', tokens_requested=2, capacity=3, refill_rate=2.0, current_time=11.0)

class DictCache:
    def __init__(self):
        self.data = {}
    def get(self, key):
        return self.data.get(key)
    def put(self, key, value):
        self.data[key] = value

cache = DictCache()
assert not allow_request(cache, 'batch', tokens_requested=6, capacity=5, refill_rate=100.0, current_time=999.0)
bucket = cache.get('rate_limit:batch')
assert bucket.tokens == 5
assert bucket.last_refill_time == 999.0
